00100 
00101 public:
00102   ReferencePictureList( const bool interLayerPicPresentFlag = false );
00103   virtual ~ReferencePictureList();
00104 
00105   void    setRefPicIdentifier( int idx, int identifier, bool isLongterm, bool isInterLayerRefPic, int interLayerIdx );
00106   int     getRefPicIdentifier(int idx) const;
00107   bool    isRefPicLongterm(int idx) const;
00108 
00109   void    setNumberOfShorttermPictures(int numberOfStrp);
00110   int     getNumberOfShorttermPictures() const;
00111 
00112   void    setNumberOfLongtermPictures(int numberOfLtrp);
00113   int     getNumberOfLongtermPictures() const;
00114 
00115   void    setLtrpInSliceHeaderFlag(bool flag) { m_ltrp_in_slice_header_flag = flag; }
00116   bool    getLtrpInSliceHeaderFlag() const { return m_ltrp_in_slice_header_flag; }
00117 
