00119   int     getNumberOfInterLayerPictures() const { return m_numberOfInterLayerPictures; }
00120 
00121   int     getNumRefEntries() const { return m_numberOfShorttermPictures + m_numberOfLongtermPictures + m_numberOfInterLayerPictures; }
00122 
00123   void    setPOC(int idx, int POC);
