00164 class ScalingList
00165 {
00166 public:
00167              ScalingList();
00168   virtual    ~ScalingList()                                                 { }
00169   
00170   int*       getScalingListAddress(uint32_t scalingListId)                    { return &(m_scalingListCoef[scalingListId][0]);            } 
00171   const int* getScalingListAddress(uint32_t scalingListId) const              { return &(m_scalingListCoef[scalingListId][0]);            } 
00172   void       checkPredMode(uint32_t scalingListId);
00173 
00174   void       setRefMatrixId(uint32_t scalingListId, uint32_t u)               { m_refMatrixId[scalingListId] = u;                         } 
00175   uint32_t       getRefMatrixId(uint32_t scalingListId) const                 { return m_refMatrixId[scalingListId];                      } 
00176 
00177   static const int* getScalingListDefaultAddress(uint32_t scalinListId);                                                                           
00178   void       processDefaultMatrix(uint32_t scalinListId);
00179 
00180   void       setScalingListDC(uint32_t scalinListId, uint32_t u)              { m_scalingListDC[scalinListId] = u;                        } 
00181   int        getScalingListDC(uint32_t scalinListId) const                    { return m_scalingListDC[scalinListId];                     } 
00182 
00183   void       setScalingListCopyModeFlag(uint32_t scalinListId, bool bIsCopy)  { m_scalingListPredModeFlagIsCopy[scalinListId] = bIsCopy;  }
00184   bool       getScalingListCopyModeFlag(uint32_t scalinListId) const          { return m_scalingListPredModeFlagIsCopy[scalinListId];     } //getScalingListPredModeFlag
00185   void       processRefMatrix(uint32_t scalingListId, uint32_t refListId);
00186 
00187   int        lengthUvlc(int uiCode);
00188   int        lengthSvlc(int uiCode);
00189   void       CheckBestPredScalingList(int scalingListId, int predListIdx, int& BitsCount);
00190   void       codePredScalingList(int* scalingList, const int* scalingListPred, int scalingListDC, int scalingListPredDC, int scalinListId, int& bitsCost);
00191   void       codeScalingList(int* scalingList, int scalingListDC, int scalinListId, int& bitsCost);
00192   void       setScalingListPreditorModeFlag(uint32_t scalingListId, bool bIsPred) { m_scalingListPreditorModeFlag[scalingListId] = bIsPred; }
00193   bool       getScalingListPreditorModeFlag(uint32_t scalingListId) const { return m_scalingListPreditorModeFlag[scalingListId]; }
00194   bool       getChromaScalingListPresentFlag() const {return m_chromaScalingListPresentFlag;}
00195   void       setChromaScalingListPresentFlag( bool flag) { m_chromaScalingListPresentFlag = flag;}
00196   bool       isLumaScalingList( int scalingListId) const;
00197   void       checkDcOfMatrix();
00198   bool       xParseScalingList(const std::string &fileName);
00199   void       setDefaultScalingList();
00200   bool       isNotDefaultScalingList();
00201 
00202   bool operator==( const ScalingList& other )
00203   {
00204     if (memcmp(m_scalingListPredModeFlagIsCopy, other.m_scalingListPredModeFlagIsCopy, sizeof(m_scalingListPredModeFlagIsCopy)))
00205     {
00206       return false;
00207     }
00208     if( memcmp( m_scalingListDC, other.m_scalingListDC, sizeof( m_scalingListDC ) ) )
00209     {
00210       return false;
00211     }
00212     if( memcmp( m_refMatrixId, other.m_refMatrixId, sizeof( m_refMatrixId ) ) )
00213     {
00214       return false;
00215     }
00216     if( memcmp( m_scalingListCoef, other.m_scalingListCoef, sizeof( m_scalingListCoef ) ) )
00217     {
00218       return false;
00219     }
00220 
00221     return true;
00222   }
00223 
00224   bool operator!=( const ScalingList& other )
00225   {
00226     return !( *this == other );
00227   }
00228 
00229 private:
00230   void             outputScalingLists(std::ostream &os) const;
00231   bool             m_scalingListPredModeFlagIsCopy [30]; 
00232   int              m_scalingListDC                 [30]; 
00233   uint32_t         m_refMatrixId                   [30]; 
00234   bool             m_scalingListPreditorModeFlag   [30]; 
00235   std::vector<int> m_scalingListCoef               [30]; 
00236   bool             m_chromaScalingListPresentFlag;
00237 };
