00597   uint32_t  reshaperModelMinBinIdx;
00598   uint32_t  reshaperModelMaxBinIdx;
00599   int       reshaperModelBinCWDelta[PIC_CODE_CW_BINS];
00600   int       maxNbitsNeededDeltaCW;
00601   int       chrResScalingOffset;
00602   void      setUseSliceReshaper(bool b)                                { sliceReshaperEnableFlag = b;            }
00603   bool      getUseSliceReshaper() const                                { return sliceReshaperEnableFlag;         }
00604   void      setSliceReshapeModelPresentFlag(bool b)                    { sliceReshaperModelPresentFlag = b;      }
00605   bool      getSliceReshapeModelPresentFlag() const                    { return   sliceReshaperModelPresentFlag; }
00606   void      setSliceReshapeChromaAdj(unsigned adj)                     { enableChromaAdj = adj;                  }
00607   unsigned  getSliceReshapeChromaAdj() const                           { return enableChromaAdj;                 }
00608 
00609   bool operator==( const SliceReshapeInfo& other )
00610   {
00611     if( sliceReshaperEnableFlag != other.sliceReshaperEnableFlag )
00612     {
00613       return false;
00614     }
00615     if( sliceReshaperModelPresentFlag != other.sliceReshaperModelPresentFlag )
00616     {
00617       return false;
00618     }
00619     if( enableChromaAdj != other.enableChromaAdj )
00620     {
00621       return false;
00622     }
00623     if( reshaperModelMinBinIdx != other.reshaperModelMinBinIdx )
00624     {
00625       return false;
00626     }
00627     if( reshaperModelMaxBinIdx != other.reshaperModelMaxBinIdx )
00628     {
00629       return false;
00630     }
00631     if( maxNbitsNeededDeltaCW != other.maxNbitsNeededDeltaCW )
00632     {
00633       return false;
00634     }
00635     if (chrResScalingOffset != other.chrResScalingOffset)
00636     {
00637       return false;
00638     }
00639     if( memcmp( reshaperModelBinCWDelta, other.reshaperModelBinCWDelta, sizeof( reshaperModelBinCWDelta ) ) )
00640     {
00641       return false;
00642     }
00643 
00644     return true;
00645   }
00646 
00647   bool operator!=( const SliceReshapeInfo& other )
00648   {
00649     return !( *this == other );
00650   }
00651 };
