00723 class SliceMap
00724 {
00725 private:
00726   uint32_t               m_sliceID;                           
00727   uint32_t               m_numTilesInSlice;                   
00728   uint32_t               m_numCtuInSlice;                     
00729   std::vector<uint32_t>  m_ctuAddrInSlice;                    
00730 
00731 public:
00732   SliceMap();
00733   virtual ~SliceMap();
00734 
00735   void                   setSliceID( uint32_t u )             { m_sliceID = u;            }
00736   uint32_t               getSliceID() const                   { return m_sliceID;         }
00737   void                   setNumTilesInSlice( uint32_t u )     { m_numTilesInSlice = u;    }
00738   uint32_t               getNumTilesInSlice() const           { return m_numTilesInSlice; }
00739   void                   setNumCtuInSlice( uint32_t u )       { m_numCtuInSlice = u;      }
00740   uint32_t               getNumCtuInSlice() const             { return m_numCtuInSlice;   }
00741   std::vector<uint32_t>  getCtuAddrList( ) const              { return m_ctuAddrInSlice;  }
00742   uint32_t               getCtuAddrInSlice( int idx ) const   { CHECK(idx >= m_ctuAddrInSlice.size(), "CTU index exceeds number of CTUs in slice."); return m_ctuAddrInSlice[idx]; }
00743   void                   pushToCtuAddrInSlice( uint32_t u )   { m_ctuAddrInSlice.push_back(u); m_numCtuInSlice++;}
00744 
00745   void  initSliceMap()
00746   {
00747     m_sliceID = 0;
00748     m_numTilesInSlice = 0;
00749     m_numCtuInSlice = 0;
00750     m_ctuAddrInSlice.clear();
00751   }
00752 
00753   void  addCtusToSlice( uint32_t startX, uint32_t stopX, uint32_t startY, uint32_t stopY, uint32_t picWidthInCtbsY )
00754   {
00755     CHECK( startX >= stopX || startY >= stopY, "Invalid slice definition");
00756     for( uint32_t ctbY = startY; ctbY < stopY; ctbY++ )
00757     {
00758       for( uint32_t ctbX = startX; ctbX < stopX; ctbX++ )
00759       {
00760         m_ctuAddrInSlice.push_back( ctbY * picWidthInCtbsY + ctbX );
00761         m_numCtuInSlice++;
00762       }
00763     }
00764   }
00765 };
