00863     for (uint32_t ctbY = startY; ctbY < stopY; ctbY++)
00864     {
00865       for (uint32_t ctbX = startX; ctbX < stopX; ctbX++)
00866       {
00867         m_ctuAddrInSubPic.push_back(ctbY * picWidthInCtbsY + ctbX);
00868       }
00869     }
00870   }
00871   bool                 isContainingPos(const Position& pos) const
00872   {
00873     return pos.x >= m_subPicLeft && pos.x <= m_subPicRight && pos.y >= m_subPicTop  && pos.y <= m_subPicBottom;
00874   }
00875   void             setTreatedAsPicFlag           (bool u)  {         m_treatedAsPicFlag = u;   }
00876   bool             getTreatedAsPicFlag           ()  const { return  m_treatedAsPicFlag;       }
00877   void             setloopFilterAcrossEnabledFlag(bool u)  {         m_loopFilterAcrossSubPicEnabledFlag = u; }
00878   bool             getloopFilterAcrossEnabledFlag()  const { return  m_loopFilterAcrossSubPicEnabledFlag;     }
00879 
00880   bool             isFirstCTUinSubPic(uint32_t ctuAddr) const { return  ctuAddr == m_firstCtuInSubPic;  }
00881   bool              isLastCTUinSubPic(uint32_t ctuAddr) const { return  ctuAddr == m_lastCtuInSubPic;   }
00882   void             setNumSlicesInSubPic( uint32_t val )    { m_numSlicesInSubPic = val; }
00883   uint32_t         getNumSlicesInSubPic() const            { return m_numSlicesInSubPic; }
00884   bool             containsCtu(const Position& pos) const
00885   {
00886     return pos.x >= m_subPicCtuTopLeftX && pos.x < m_subPicCtuTopLeftX + m_subPicWidth &&
00887            pos.y >= m_subPicCtuTopLeftY && pos.y < m_subPicCtuTopLeftY + m_subPicHeight;
00888   }
00889   bool             containsCtu(int ctuAddr) const
00890   {
00891     for (auto & addr : m_ctuAddrInSubPic)
00892     {
00893       if (addr == ctuAddr)
00894       {
00895         return true;
00896       }
00897     }
00898     return false;
00899   }
00900 };
