01155 class Window
01156 {
01157 private:
01158   bool m_enabledFlag;
01159   int  m_winLeftOffset;
01160   int  m_winRightOffset;
01161   int  m_winTopOffset;
01162   int  m_winBottomOffset;
01163 public:
01164   Window()
01165   : m_enabledFlag    (false)
01166   , m_winLeftOffset  (0)
01167   , m_winRightOffset (0)
01168   , m_winTopOffset   (0)
01169   , m_winBottomOffset(0)
01170   { }
01171 
01172   bool getWindowEnabledFlag() const   { return m_enabledFlag;                          }
01173   int  getWindowLeftOffset() const    { return m_enabledFlag ? m_winLeftOffset : 0;    }
01174   void setWindowLeftOffset(int val)   { m_winLeftOffset = val; m_enabledFlag |=  (val!=0);   }
01175   int  getWindowRightOffset() const   { return m_enabledFlag ? m_winRightOffset : 0;   }
01176   void setWindowRightOffset(int val)  { m_winRightOffset = val; m_enabledFlag |= (val!=0);  }
01177   int  getWindowTopOffset() const     { return m_enabledFlag ? m_winTopOffset : 0;     }
01178   void setWindowTopOffset(int val)    { m_winTopOffset = val; m_enabledFlag |= (val!=0);    }
01179   int  getWindowBottomOffset() const  { return m_enabledFlag ? m_winBottomOffset: 0;   }
01180   void setWindowBottomOffset(int val) { m_winBottomOffset = val; m_enabledFlag |= (val!=0); }
01181 
01182   void setWindow(int offsetLeft, int offsetRight, int offsetTop, int offsetBottom)
01183   {
01184     m_enabledFlag     = (offsetLeft || offsetRight || offsetTop || offsetBottom);
01185     m_winLeftOffset   = offsetLeft;
01186     m_winRightOffset  = offsetRight;
01187     m_winTopOffset    = offsetTop;
01188     m_winBottomOffset = offsetBottom;
01189   }
01190 };
