02045   void                   setQpOffset(ComponentID compID, int i )
02046   {
02047     if      (compID==COMPONENT_Cb)
02048     {
02049       m_chromaCbQpOffset = i;
02050     }
02051     else if (compID==COMPONENT_Cr)
02052     {
02053       m_chromaCrQpOffset = i;
02054     }
02055     else if (compID==JOINT_CbCr)
02056     {
02057       m_chromaCbCrQpOffset = i;
02058     }
02059     else
02060     {
02061       THROW( "Invalid chroma QP offset" );
02062     }
02063   }
02064   int                    getQpOffset(ComponentID compID) const
02065   {
02066     return (compID==COMPONENT_Y) ? 0 : (compID==COMPONENT_Cb ? m_chromaCbQpOffset : compID==COMPONENT_Cr ? m_chromaCrQpOffset : m_chromaCbCrQpOffset );
02067   }
