02301 struct WPScalingParam
02302 {
02303   // Explicit weighted prediction parameters parsed in slice header,
02304   // or Implicit weighted prediction parameters (8 bits depth values).
02305   bool     presentFlag;
02306   uint32_t log2WeightDenom;
02307   int      codedWeight;
02308   int      codedOffset;
02309 
02310   // Weighted prediction scaling values built from above parameters (bitdepth scaled):
02311   int  w;
02312   int  o;
02313   int  offset;
02314   int  shift;
02315   int  round;
02316 
02317   static bool isWeighted(const WPScalingParam *wp);
02318 };
02319 
02320 inline bool WPScalingParam::isWeighted(const WPScalingParam *wp)
02321 {
02322   return wp != nullptr && (wp[COMPONENT_Y].presentFlag || wp[COMPONENT_Cb].presentFlag || wp[COMPONENT_Cr].presentFlag);
02323 }
