03034 class PreCalcValues
03035 {
03036 public:
03037   PreCalcValues( const SPS& sps, const PPS& pps, bool _isEncoder )
03038     : chrFormat           ( sps.getChromaFormatIdc() )
03039     , multiBlock422       ( false )
03040     , maxCUWidth          ( sps.getMaxCUWidth() )
03041     , maxCUHeight         ( sps.getMaxCUHeight() )
03042     , maxCUWidthMask      ( maxCUWidth  - 1 )
03043     , maxCUHeightMask     ( maxCUHeight - 1 )
03044     , maxCUWidthLog2      ( floorLog2( maxCUWidth  ) )
03045     , maxCUHeightLog2     ( floorLog2( maxCUHeight ) )
03046     , minCUWidth          ( 1 << MIN_CU_LOG2 )
03047     , minCUHeight         ( 1 << MIN_CU_LOG2 )
03048     , minCUWidthLog2      ( floorLog2( minCUWidth  ) )
03049     , minCUHeightLog2     ( floorLog2( minCUHeight ) )
03050     , partsInCtuWidth     ( maxCUWidth >> MIN_CU_LOG2)
03051     , partsInCtuHeight    ( maxCUHeight >> MIN_CU_LOG2)
03052     , partsInCtu          ( partsInCtuWidth * partsInCtuHeight )
03053     , widthInCtus         ( (pps.getPicWidthInLumaSamples () + sps.getMaxCUWidth () - 1) / sps.getMaxCUWidth () )
03054     , heightInCtus        ( (pps.getPicHeightInLumaSamples() + sps.getMaxCUHeight() - 1) / sps.getMaxCUHeight() )
03055     , sizeInCtus          ( widthInCtus * heightInCtus )
03056     , lumaWidth           ( pps.getPicWidthInLumaSamples() )
03057     , lumaHeight          ( pps.getPicHeightInLumaSamples() )
03058     , fastDeltaQPCuMaxSize( Clip3(1u << sps.getLog2MinCodingBlockSize(), sps.getMaxCUHeight(), 32u) )
03059     , noChroma2x2         (  false )
03060     , isEncoder           ( _isEncoder )
03061     , ISingleTree         ( !sps.getUseDualITree() )
03062     , maxBtDepth          { sps.getMaxMTTHierarchyDepthI(), sps.getMaxMTTHierarchyDepth(), sps.getMaxMTTHierarchyDepthIChroma() }
03063     , minBtSize           { 1u << sps.getLog2MinCodingBlockSize(), 1u << sps.getLog2MinCodingBlockSize(), 1u << sps.getLog2MinCodingBlockSize() }
03064     , maxBtSize           { sps.getMaxBTSizeI(), sps.getMaxBTSize(), sps.getMaxBTSizeIChroma() }
03065     , minTtSize           { 1u << sps.getLog2MinCodingBlockSize(), 1u << sps.getLog2MinCodingBlockSize(), 1u << sps.getLog2MinCodingBlockSize() }
03066     , maxTtSize           { sps.getMaxTTSizeI(), sps.getMaxTTSize(), sps.getMaxTTSizeIChroma() }
03067     , minQtSize           { sps.getMinQTSize(I_SLICE, CHANNEL_TYPE_LUMA), sps.getMinQTSize(B_SLICE, CHANNEL_TYPE_LUMA), sps.getMinQTSize(I_SLICE, CHANNEL_TYPE_CHROMA) }
03068   {}
03069 
03070   const ChromaFormat chrFormat;
03071   const bool         multiBlock422;
03072   const unsigned     maxCUWidth;
03073   const unsigned     maxCUHeight;
03074   // to get CTU position, use (x & maxCUWidthMask) rather than (x % maxCUWidth)
03075   const unsigned     maxCUWidthMask;
03076   const unsigned     maxCUHeightMask;
03077   const unsigned     maxCUWidthLog2;
03078   const unsigned     maxCUHeightLog2;
03079   const unsigned     minCUWidth;
03080   const unsigned     minCUHeight;
03081   const unsigned     minCUWidthLog2;
03082   const unsigned     minCUHeightLog2;
03083   const unsigned     partsInCtuWidth;
03084   const unsigned     partsInCtuHeight;
03085   const unsigned     partsInCtu;
03086   const unsigned     widthInCtus;
03087   const unsigned     heightInCtus;
03088   const unsigned     sizeInCtus;
03089   const unsigned     lumaWidth;
03090   const unsigned     lumaHeight;
03091   const unsigned     fastDeltaQPCuMaxSize;
03092   const bool         noChroma2x2;
03093   const bool         isEncoder;
03094   const bool         ISingleTree;
03095 
03096 private:
03097   const unsigned     maxBtDepth[3];
03098   const unsigned     minBtSize [3];
03099   const unsigned     maxBtSize [3];
03100   const unsigned     minTtSize [3];
03101   const unsigned     maxTtSize [3];
03102   const unsigned     minQtSize [3];
